---@param type EHeadType_RenderQueue
---@param headPart EHeadPart
function this:GetEHeadType_RenderQueueData_CloneMats(type,headPart)
    return self.EHeadType_RenderQueueData[type] and self.EHeadType_RenderQueueData[type].cloneMats[headPart]
end

function this:GetEHeadType_RenderQueueData_RenderQueue(type_,headPart,index)
    if self.EHeadType_RenderQueueData[type_]  then
        if self.EHeadType_RenderQueueData[type_].renderQueue_headParts[headPart] and index then
            if type(self.EHeadType_RenderQueueData[type_].renderQueue_headParts[headPart])=="table" then
                return self.EHeadType_RenderQueueData[type_].renderQueue_headParts[headPart][index] or self.EHeadType_RenderQueueData[type_].renderQueue
            else
                return self.EHeadType_RenderQueueData[type_].renderQueue_headParts[headPart]
            end
        end
        if (headPart == EHeadPart.Talk_Part or headPart == EHeadPart.StallName_Part) and index == 2 then
            return self.EHeadType_RenderQueueData[type_].renderQueue - 1
        end
        return self.EHeadType_RenderQueueData[type_].renderQueue
    end
    
end

---@param e_headPart EHeadPart
---@param parent UnityEngine.Transform
function this:Pop(e_headPart,parent)
    local data = self.list[e_headPart]
    if data then
        local go
        ---@type EHeadPart_Data
        local headData = self.HeadPart_DataList[e_headPart]
        local isCreate = false
        if #data > 0 then
            go = table.remove(data,1)
        else
            Async.SwitchFunc(not Main.isLoadResAsync, function()
                local obj = PreLoadUIManager.others[PreLoadUIManager.othersPath[EPreLoadHeadPart[e_headPart]]]
                if IsNil(obj) then
                    go = GameObject.Instantiate(PreLoadUIManager.othersPath[EPreLoadHeadPart[e_headPart]]).gameObject
                    logError("HeadPool:Pop obj==nil 没找到预制体 path="..PreLoadUIManager.othersPath[EPreLoadHeadPart[e_headPart]])
                else
                    go = GameObject.Instantiate(obj).gameObject
                end
                if not IsNil(go) then
                    go.name = obj.name
                end
            end, function()
                local obj = PreLoadUIManager.others[PreLoadUIManager.othersPath[EPreLoadHeadPart[e_headPart]]]
                if IsNil(obj) then
                    go = GameObject.Instantiate(PreLoadUIManager.othersPath[EPreLoadHeadPart[e_headPart]]).gameObject
                    logError("HeadPool:Pop obj==nil 没找到预制体 path="..PreLoadUIManager.othersPath[EPreLoadHeadPart[e_headPart]])
                else
                    go = GameObject.Instantiate(obj).gameObject
                end
                if not IsNil(go) then
                    go.name = obj.name
                end
            end)
            isCreate = true
        end
        self:InitGo(go,parent,headData.pos,headData.scale,headData.rotate,headData.fontsize or 16)
        return go,isCreate
    end
end

---@param e_headPart EHeadPart
---@param go UnityEngine.GameObject
function this:Push(e_headPart,go)
    if not IsNil(go) then
        local data = self.list[e_headPart]
        local maxSaveCount = self.maxSaveCountList[e_headPart] or 10
        if data and table.count(data) < maxSaveCount then
            if not table.contains(data,go) then
                table.insert(data,1,go)
                if IsNil(self.headPool) then
                    self.headPool = GameObject.Find("HeadPool") or GameObject("HeadPool")
                    GameObject.DontDestroyOnLoad(self.headPool)
                    self.headPool:SetActive(false)
                end
                go.transform:SetParentAndIdentity(self.headPool.transform)
            end
        else
            GameObject.DestroyImmediate(go.gameObject)
        end
    end
end


---@param e_headPart EHeadPart
---@param parent UnityEngine.Transform
function this:Out_Pop(e_headPart,instantiateGo,parent,pos,scale,rotate)

    if IsNil(instantiateGo) then
        return
    end
    
    local data = self.out_list[e_headPart]
    if not data then
        data = {}
        self.out_list[e_headPart] = data
    end
    
    if data then
        local go
        if #data > 0 then
            go = table.remove(data,1)
        else
            if IsNil(instantiateGo) then
                return go
            end
            Async.SwitchFunc(not Main.isLoadResAsync, function()
                local obj = instantiateGo
                if IsNil(obj) then
                    go = GameObject.Instantiate(instantiateGo).gameObject
                    logError("HeadPool:Pop obj==nil 没找到预制体 e_headPart="..e_headPart)
                else
                    go = GameObject.Instantiate(obj).gameObject
                end
                if not IsNil(go) then
                    go.name = obj.name
                end
            end, function()
                local obj = instantiateGo
                if IsNil(obj) then
                    go = GameObject.Instantiate(instantiateGo).gameObject
                    logError("HeadPool:Pop obj==nil 没找到预制体 e_headPart="..e_headPart)
                else
                    go = GameObject.Instantiate(obj).gameObject
                end
                if not IsNil(go) then
                    go.name = obj.name
                end
            end)
        end
        self:InitGo(go,parent,pos,scale,rotate)
        return go
    end
end

---@param e_headPart EHeadPart
---@param go UnityEngine.GameObject
function this:Out_Push(e_headPart,go)
    if not IsNil(go) then
        local data = self.out_list[e_headPart]

        if not data then
            data = {}
            self.out_list[e_headPart] = data
        end
        
        local maxSaveCount = 20
        if data and table.count(data) < maxSaveCount then
            if not table.contains(data,go) then
                table.insert(data,1,go)
                if IsNil(self.headPool) then
                    self.headPool = GameObject.Find("HeadPool") or GameObject("HeadPool")
                    GameObject.DontDestroyOnLoad(self.headPool)
                    self.headPool:SetActive(false)
                end
                go.transform:SetParentAndIdentity(self.headPool.transform)
            end
        else
            GameObject.DestroyImmediate(go.gameObject)
        end
    end
end

function this:Release()
    self:Clear()
end

---@param go UnityEngine.GameObject
---@param parent UnityEngine.Transform
---@param pos Vector3
---@param scale Vector3
---@param rotate Vector3
---@param fontsize number
function this:InitGo(go,parent,pos,scale,rotate,fontsize)
    if not IsNil(go) then
        if not IsNil(parent) then
            go.transform:SetParent(parent)
        end
        if pos then
            go.transform:SetLocalPosition(pos.x,pos.y,pos.z)
        end
        if rotate then
            go.transform:SetLocalEulerAngles(rotate.x,rotate.y,rotate.z)
        end
        if scale then
            go.transform:SetLocalScale(scale.x,scale.y,scale.z)
        end
        if fontsize then
            local lab = UtilityLua.Get(go.transform, "", typeof(CS.CSLabel))
            if not lab then
                lab = UtilityLua.Get(go.transform, '', typeof(CS.CSMultiLabel))
                if lab then
                    lab.template.fontSize = fontsize
                end
            elseif lab then
                lab.fontSize = fontsize
            end
        end
    end
end

