function this:Clear()
    for i, tb in pairs(self.list) do
        for j, go in pairs(tb) do
            if not IsNil(go) then
                GameObject.DestroyImmediate(go.gameObject)
            end
        end
        table.clear(tb)
    end

    for i, tb in pairs(self.out_list) do
        for j, go in pairs(tb) do
            if not IsNil(go) then
                GameObject.DestroyImmediate(go.gameObject)
            end
        end
        table.clear(tb)
    end
end